import React, { useState, useEffect, useRef } from 'react';
import './index.css';

const App: React.FC = () => {
  const [input, setInput] = useState('');
  const [output, setOutput] = useState<string[]>(["Welcome to my portfolio! Type `help` to see available commands."]);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInput(e.target.value);
  };

  const handleInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      let newOutput = [...output, `> ${input}`];

      switch (input.toLowerCase()) {
        case 'help':
          newOutput.push('Available commands: help, about, projects, skills, contact, clear');
          break;
        case 'about':
          newOutput.push('This is my interactive portfolio. I am a software engineer with a passion for creating beautiful and functional applications.');
          break;
        case 'projects':
          newOutput.push('Here are some of my projects:');
          newOutput.push('- Project 1: A brief description of the project.');
          newOutput.push('- Project 2: A brief description of the project.');
          newOutput.push('- Project 3: A brief description of the project.');
          break;
        case 'skills':
          newOutput.push('My skills include: JavaScript, TypeScript, React, Node.js, Python, and more.');
          break;
        case 'contact':
          newOutput.push('You can reach me at: myemail@example.com');
          break;
        case 'clear':
          newOutput = [];
          break;
        default:
          newOutput.push(`Command not found: ${input}`);
          break;
      }

      setOutput(newOutput);
      setInput('');
    }
  };

  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.focus();
    }
  }, []);

  return (
    <div className="container">
      <div className="output">
        {output.map((line, index) => (
          <div
            key={index}
            className={
              line.startsWith('>')
                ? 'command-color'
                : line.startsWith('Command not found')
                ? 'error-color'
                : 'output-color'
            }
          >
            <span className="typewriter">{line}</span>
          </div>
        ))}
      </div>
      <div className="input-line">
        <span>&gt;</span>
        <input
          type="text"
          value={input}
          onChange={handleInputChange}
          onKeyDown={handleInputKeyDown}
          ref={inputRef}
          autoFocus
        />
        <span className="cursor"></span>
      </div>
    </div>
  );
};

export default App;
